 3	use Modules\AI\Domain\Decision\DefenseNeedEvaluator;
 4	use Modules\AI\Enums\AiWorkKind;
 5	use Modules\AI\Tests\Support\Situation;
 6	use OGame\Factories\PlanetServiceFactory;
 7	use OGame\Models\Planet;
 8	use Tests\IsolatedAccountTestCase;
 9	
10	require_once __DIR__ . '/../../Support/Situation.php';
11	
12	uses(IsolatedAccountTestCase::class);
13	
14	// QUAL-003's live shape (invariant:NAKED_BESIDE_WALLED, aspect:shipyard): the invariant is read on the
15	// live cohort, so this planted story is the fast reproduction of it. The cohort read found an account
16	// holding a wall on one planet while a young colony stood at zero defence: the wall waits on a shipyard the
17	// colony does not have yet, and the account kept spending its yard elsewhere. An account whose sibling
18	// already holds a wall has to bring the shipyard and then the wall to the bare colony, instead of leaving
19	// it naked for as long as it plays.
20	test('an account whose sibling holds a wall reaches the colony that has no shipyard yet', function (): void {
21	    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();
22	
23	    $situation = Situation::of($this)
24	        ->level('robot_factory', 2)
25	        ->level('shipyard', 4)
26	        ->defence('rocket_launcher', 30)
27	        ->colony()
28	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
29	        ->sessions(8, 30);
30	
31	    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
32	        ->whereNotIn('id', $before)->value('id');
33	    $colony = app(PlanetServiceFactory::class)->make($colonyId, true);
34	
35	    expect(app(DefenseNeedEvaluator::class)->standingUnits($colony))->toBeGreaterThan(0, 'expected the wall on the colony that started without a shipyard; ' . $situation->account());
36	});
37	
38	// The live residual (player 64): the sibling that stands at zero is the poor one. Its homeworld holds a
39	// wall and the account's own stock, while the colony was founded with nothing and never funded -- so the
40	// yard its wall waits on is never paid for and the planet stays naked however often the account logs in.
41	test('a naked colony with no stock of its own is still walled by an account that holds a wall', function (): void {
42	    $before = Planet::query()->where('user_id', $this->currentUserId)->pluck('id')->all();
43	
44	    $situation = Situation::of($this)
45	        ->level('robot_factory', 2)
46	        ->level('shipyard', 4)
47	        ->defence('rocket_launcher', 30)
48	        ->ships('small_cargo', 10)
49	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
50	        ->colony()
51	        ->sessions(8, 30);
52	
53	    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
54	        ->whereNotIn('id', $before)->value('id');
55	    $colony = app(PlanetServiceFactory::class)->make($colonyId, true);
56	
57	    expect(app(DefenseNeedEvaluator::class)->standingUnits($colony))->toBeGreaterThan(0, 'the unfunded colony stayed at zero defence; ' . $situation->account());
58	});
59	
60	// The walled homeworld spends a login on the sibling that holds nothing rather than on growing the wall it
61	// already has. The colony is planted first so the sibling is bare from the moment the wall stands.
62	test('a walled homeworld reaches its naked colony with a wall order', function (): void {
63	    $situation = Situation::of($this)
64	        ->levelEveryPlanet('robot_factory', 2)
65	        ->levelEveryPlanet('shipyard', 4)
66	        ->levelEveryPlanet('solar_plant', 30)
67	        ->colony()
68	        ->defence('light_laser', 1_200)
69	        ->stockEveryPlanet(5_000_000, 5_000_000, 5_000_000)
70	        ->session();
71	
72	    $situation->expectQueued('rocket_launcher')
73	        ->expectWork(AiWorkKind::QueueUnits);
74	});

