    3	namespace Modules\AI\Domain\Decision;
    4	
    5	use Modules\AI\Models\AiProfile;
    6	use OGame\Factories\PlayerServiceFactory;
    7	use OGame\GameMissions\TransportMission;
    8	use OGame\Models\Enums\PlanetType;
    9	use OGame\Models\FleetMission;
   10	use OGame\Models\Resources;
   11	use OGame\Models\User;
   12	use OGame\Services\ObjectService;
   13	use OGame\Services\PlanetService;
   14	use OGame\Services\PlayerService;
   15	
   16	/**
   17	 * Whether this account should ferry resources from one of its bodies to another, and which.
   18	 *
   19	 * A colony that cannot pay for its next level waits on the homeworld's surplus; a player looks at
   20	 * what the colony wants to build next, subtracts what is already on it and already flying to it, and
   21	 * ships the difference from the planet that can spare it without starving itself (E4/X1). The
   22	 * shortfall is netted against in-flight transports so one hole is never funded twice, the source must
   23	 * keep its reserve (SP5), and a shipment below the ordinary minimum is not worth the fleet's time.
   24	 *
   25	 * Nothing here names a game object. What a planet wants next is the same host-quoted step the
   26	 * economy planner asks -- storage overflow, energy, the facility chain, then the best mine -- and its
   27	 * price is the host's price, so an extension that adds a build or a resource changes the ferry with
   28	 * no module edit.
   29	 */
   30	class QueueableTransferPlanner
   31	{
   32	    /**
   33	     * r4fek's documented floor: combined metal and crystal below this is not worth a shipment.
   34	     * Shared with the dispatch adapter, which re-applies it to the clamped amount rather than
   35	     * flying a fleet for what is left of a spent surplus.
   36	     */
   37	    public const MINIMUM_SHIPMENT = 50_000;
   38	
   39	    /** A planet at this fraction of its storage is about to overflow and is swept (E9). */
   40	    private const SURPLUS_RATIO = 0.8;
   41	
   42	    public function __construct(
   43	        private PlayerServiceFactory $playerServiceFactory,
   44	        private EconomyUpgrades $economyUpgrades,
   45	        private EnergyCapacity $energyCapacity,
   46	        private FacilityChain $facilityChain,
   47	        private ReserveFloor $reserveFloor,
   48	    ) {
   49	    }
   50	
   51	    public function plan(int $playerId): ?QueueableTransfer
   52	    {
   53	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
   54	        if ($profile === null) {
   55	            return null;
   56	        }
   57	
   58	        if (!User::query()->whereKey($playerId)->exists()) {
   59	            return null;
   60	        }
   61	
   62	        $player = $this->playerServiceFactory->make($playerId, true);
   63	        $planets = $player->planets->all();
   64	        if (count($planets) < 2) {
   65	            return null;
   66	        }
   67	
   68	        foreach ($planets as $planet) {
   69	            $planet->updateResources(false);
   70	            $planet->updateResourceProductionStats(false);
   71	            $planet->updateResourceStorageStats(false);
   72	        }
   73	
   74	        foreach ($planets as $target) {
   75	            // A planet that stands bare beside a walled sibling is funded whatever the step costs:
   76	            // the yard its wall waits on is cheap, so the ordinary shipment floor would leave it
   77	            // unpaid and the planet naked for good (measured live 3 Oct 2026: player 64, one planet
   78	            // at zero defence while a sibling held 1,707 units).
   79	            $wall = $this->needsWallFunding($target);
   80	            $need = $this->need($target, $profile, $playerId);
   81	            if ($need === null) {
   82	                continue;
   83	            }
   84	
   85	            // The wall-funded planet flies on any real shortfall, but never on nothing: a planet
   86	            // that already holds the step's price is one its own building queue can pay for.
   87	            $funded = $wall ? $need->sum() > 0 : $this->worthShipping($need);
   88	            if (! $funded) {
   89	                continue;
   90	            }
   91	
   92	            $source = $this->source($planets, $target, $need, $player);
   93	            if ($source === null) {
   94	                continue;
   95	            }
   96	
   97	            return app()->makeWith(QueueableTransfer::class, [
   98	                'sourcePlanetId' => $source->getPlanetId(),
   99	                'targetPlanetId' => $target->getPlanetId(),
  100	                'metal' => (int) round($need->metal->get()),
  101	                'crystal' => (int) round($need->crystal->get()),
  102	                'deuterium' => (int) round($need->deuterium->get()),
  103	            ]);
  104	        }
  105	
  106	        return $this->surplus($planets, $player);
  107	    }
  108	
  109	    /**
  110	     * The reverse of the need-driven ferry: a planet about to overflow ships its
  111	     * above-floor surplus to the best-developed body, so the mines do not stall
  112	     * (E9/X2). A moon keeps its deuterium for fleet jumps; a planet sweeps all
  113	     * three resources.
  114	     *
  115	     * @param array<PlanetService> $planets
  116	     */
  117	    private function surplus(array $planets, PlayerService $player): ?QueueableTransfer
  118	    {
  119	        $drop = $this->dropBody($planets);
  120	        if ($drop === null) {
  121	            return null;
  122	        }
  123	
  124	        foreach ($planets as $source) {
  125	            if ($source->getPlanetId() === $drop->getPlanetId() || !$this->nearCap($source)) {
  126	                continue;
  127	            }
  128	
  129	            $floor = $this->reserveFloor->floor($source, ReserveFloor::ECONOMY_HOURS);
  130	            $shipment = $this->aboveFloor($source, $floor, $source->getPlanetType() === PlanetType::Moon);
  131	            if (!$this->worthShipping($shipment) || !$this->hasCargo($source, $player)) {
  132	                continue;
  133	            }
  134	
  135	            return app()->makeWith(QueueableTransfer::class, [
  136	                'sourcePlanetId' => $source->getPlanetId(),
  137	                'targetPlanetId' => $drop->getPlanetId(),
  138	                'metal' => (int) round($shipment->metal->get()),
  139	                'crystal' => (int) round($shipment->crystal->get()),
  140	                'deuterium' => (int) round($shipment->deuterium->get()),
  141	            ]);
  142	        }
  143	
  144	        return null;
  145	    }
  146	
  147	    /**
  148	     * The most developed own planet, by the host's building count: the drop the
  149	     * surplus consolidates onto. Moons are never the drop.
  150	     *
  151	     * @param array<PlanetService> $planets
  152	     */
  153	    private function dropBody(array $planets): ?PlanetService
  154	    {
  155	        $best = null;
  156	        foreach ($planets as $planet) {
  157	            if ($planet->getPlanetType() === PlanetType::Moon) {
  158	                continue;
  159	            }
  160	
  161	            if ($best === null || $planet->getBuildingCount() > $best->getBuildingCount()) {
  162	                $best = $planet;
  163	            }
  164	        }
  165	
  166	        return $best;
  167	    }
  168	
  169	    /** Whether either stored resource is at or past the near-cap threshold. */
  170	    private function nearCap(PlanetService $planet): bool
  171	    {
  172	        return $planet->metal()->get() >= self::SURPLUS_RATIO * $planet->metalStorage()->get()
  173	            || $planet->crystal()->get() >= self::SURPLUS_RATIO * $planet->crystalStorage()->get();
  174	    }
  175	
  176	    /** What a body ships above its reserve floor; a moon keeps its deuterium. */
  177	    private function aboveFloor(PlanetService $source, Resources $floor, bool $keepDeuterium): Resources
  178	    {
  179	        return new Resources(
  180	            max(0.0, $source->metal()->get() - $floor->metal->get()),
  181	            max(0.0, $source->crystal()->get() - $floor->crystal->get()),
  182	            $keepDeuterium ? 0.0 : max(0.0, $source->deuterium()->get() - $floor->deuterium->get()),
  183	        );
  184	    }
  185	
  186	    /**
  187	     * What this planet is short for its next level: its price minus what is already there and already
  188	     * flying to it, floored at zero so a planet that has enough ships nothing.
  189	     */
  190	    private function need(PlanetService $target, AiProfile $profile, int $playerId): ?Resources
  191	    {
  192	        $price = $this->nextStepPrice($target, $profile);
  193	        if ($price === null) {
  194	            return null;
  195	        }
  196	
  197	        $inFlight = $this->inFlightTo($target, $playerId);
  198	
  199	        return new Resources(
  200	            max(0.0, $price->metal->get() - $target->metal()->get() - $inFlight->metal->get()),
  201	            max(0.0, $price->crystal->get() - $target->crystal()->get() - $inFlight->crystal->get()),
  202	            max(0.0, $price->deuterium->get() - $target->deuterium()->get() - $inFlight->deuterium->get()),
  203	        );
  204	    }
  205	
  206	    /**
  207	     * The next level this planet wants, in the same order the economy planner takes: storage that is
  208	     * about to overflow, energy before the throttle, the chain's facilities, then the best mine.
  209	     */
  210	    private function nextStepPrice(PlanetService $planet, AiProfile $profile): ?Resources
  211	    {
  212	        // The wall's own prerequisite outranks the shipment floor: a planet bare beside a walled
  213	        // sibling is the one the account has already decided wants a wall, and the yard it waits on
  214	        // costs far less than an ordinary ferry, so the floor below would never fund it.
  215	        $wall = $this->facilityChain->wallPending($planet);
  216	        if ($wall !== []) {
  217	            return ObjectService::getObjectPrice(ObjectService::getObjectById($wall[0]->buildingId)->machine_name, $planet);
  218	        }
  219	
  220	        $candidates = [
  221	            ...$this->economyUpgrades->storage($planet, $profile),
  222	            ...$this->energyCapacity->pending($planet),
  223	            ...$this->facilityChain->pending($planet),
  224	            ...$this->economyUpgrades->production($planet, $profile),
  225	        ];
  226	
  227	        // The ferry funds the step the planet cannot reach on its own, so a candidate whose whole
  228	        // price is below the shipment floor -- a cheap research the planet pays for from an hour of
  229	        // income -- is not the shortfall a player ships resources for; the next step down the same
  230	        // list is.
  231	        foreach ($candidates as $candidate) {
  232	            $price = ObjectService::getObjectPrice(ObjectService::getObjectById($candidate->buildingId)->machine_name, $planet);
  233	            if ($this->worthShipping($price)) {
  234	                return $price;
  235	            }
  236	        }
  237	
  238	        return null;
  239	    }
  240	
  241	    /**
  242	     * Whether this planet stands bare beside a walled sibling: the one state the ferry funds below
  243	     * the ordinary shipment floor, because the account has already decided the planet wants a wall
  244	     * and only its yard is missing.
  245	     */
  246	    private function needsWallFunding(PlanetService $planet): bool
  247	    {
  248	        return $this->facilityChain->wallPending($planet) !== [];
  249	    }
  250	
  251	    /**
  252	     * The account's own transports already on the way to this body, netted off before the shortfall.
  253	     */
  254	    private function inFlightTo(PlanetService $target, int $playerId): Resources
  255	  
